pub fn tangent(r: Vec<u64>, x: Vec<u64>) -> bool {
    // For each element in `r`, attempt to find it in `x` via binary_search.
    // As soon as we see is_ok(), we know there is at least one common value.
    r.iter().any(|&v| x.binary_search(&v).is_ok())
}

